//! Restricted Rust source backend for the integer range-sum kernel.
use crate::{
    ast::Node,
    error::AzaError,
    interpreter::{compile_range_kernel_from_node, IntKernelOp},
};

pub fn emit_rust(program: &Node) -> Result<String, AzaError> {
    let kernel = compile_range_kernel_from_node(program).ok_or_else(|| {
        AzaError::new("このプログラムはRustコード生成の対象外です（整数の連番合計のみ対応）")
    })?;
    let mut source = String::from(
        "// Generated by AZAORI. None means the checked integer kernel overflowed.\n\
         fn run() -> Option<i64> {\n\
             let mut total = 0_i64;\n\
             for input in 1_i64..=",
    );
    source.push_str(&kernel.count.to_string());
    source.push_str("_i64 {\n        let mut term = input;\n");
    for operation in kernel.operations {
        let expression = match operation {
            IntKernelOp::Add(value) => format!("term.checked_add({value}_i64)?"),
            IntKernelOp::Sub(value) => format!("term.checked_sub({value}_i64)?"),
            IntKernelOp::Mul(value) => format!("term.checked_mul({value}_i64)?"),
            IntKernelOp::Double => "term.checked_add(term)?".into(),
            IntKernelOp::Square => "term.checked_mul(term)?".into(),
        };
        source.push_str("        term = ");
        source.push_str(&expression);
        source.push_str(";\n");
    }
    source.push_str(
        "        total = total.checked_add(term)?;\n\
             }\n\
             Some(total)\n\
         }\n\n\
         fn main() {\n\
             match run() {\n\
                 Some(value) => println!(\"{value}\"),\n\
                 None => {\n\
                     eprintln!(\"整数範囲を超えました。元のAZAORIプログラムで実行してください\");\n\
                     std::process::exit(1);\n\
                 }\n\
             }\n\
         }\n",
    );
    Ok(source)
}

#[cfg(test)]
mod tests {
    use super::emit_rust;

    #[test]
    fn emits_checked_code_for_supported_kernel() {
        let program = crate::parser::parse("10 連 自掛 総足").unwrap();
        let source = emit_rust(&program).unwrap();
        assert!(source.contains("for input in 1_i64..=10_i64"));
        assert!(source.contains("term.checked_mul(term)?"));
        assert!(source.contains("total.checked_add(term)?"));
    }

    #[test]
    fn rejects_programs_outside_the_kernel_subset() {
        let program = crate::parser::parse("10 連 足 1").unwrap();
        assert!(emit_rust(&program).is_err());
    }
}
